<script setup>
import LocalizedStatusBadge from '@/shared/presentation/components/LocalizedStatusBadge.vue'
import ContextPageHeading from '@/shared/presentation/components/ContextPageHeading.vue'
import { useRecordNavigation } from '@/shared/presentation/composables/useRecordNavigation'
import { computed, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import { useAuthStore } from '@/boundedcontext/identityaccess/application/stores/auth.store'
import { useSafeLabDemoStore } from '@/shared/application/stores/demo.store'
const auth = useAuthStore(); const demo = useSafeLabDemoStore(); const { t } = useI18n(); auth.restoreSession()
const typeFilter = ref('all')
const user = computed(() => auth.currentUser)
const actuators = computed(() => demo.scopedItems('actuators', user.value).filter((a) => typeFilter.value === 'all' || a.type === typeFilter.value))
const summary = computed(() => ({ total: actuators.value.length, available: actuators.value.filter(a=>a.status==='online' && a.safetyState==='enabled').length, blocked: actuators.value.filter(a=>a.status!=='online' || a.safetyState==='blocked').length, executed: demo.remoteCommands.length }))
function command(actuator, action){
  if(!auth.hasPermission('actuation.execute') || actuator.status!=='online' || actuator.safetyState!=='enabled') return
  const message = t('uiReview.remoteConfirm',{action:t(`platformUi.state_${action.toLowerCase()}`),device:actuator.name})
  if(window.confirm(message)) demo.executeCommand(actuator.id, action, user.value?.fullName || 'SafeLab Administrator')
}
const { openRecords } = useRecordNavigation()
</script>
<template>
  <section class="page">
    <div class="page-hero compact"><ContextPageHeading :description="$t('legacy.label_515b18f170')" /></div>
    <div class="kpi-grid"><article class="kpi-card"><span class="kpi-icon"><i class="pi pi-sliders-h"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_e75b27caa7') }}</span><strong>{{ summary.total }}</strong><small>{{ $t('legacy.label_6a5ae9a274') }}</small></div></article><article class="kpi-card success"><span class="kpi-icon"><i class="pi pi-check"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_7c62a14244') }}</span><strong>{{ summary.available }}</strong><small>{{ $t('legacy.label_6216eb9394') }}</small></div></article><article class="kpi-card warning"><span class="kpi-icon"><i class="pi pi-lock"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_99613c74ce') }}</span><strong>{{ summary.blocked }}</strong><small>{{ $t('legacy.label_5113a6bd55') }}</small></div></article><article class="kpi-card"><span class="kpi-icon"><i class="pi pi-history"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_04632d0dc4') }}</span><strong>{{ summary.executed }}</strong><small>{{ $t('legacy.label_14e359f340') }}</small></div></article></div>
    <div class="filter-bar"><div class="field"><label>{{ $t('legacy.label_41f1359215') }}</label><select v-model="typeFilter" class="select"><option value="all">{{ $t('legacy.label_30c8a0fc9c') }}</option><option value="Relay">{{ $t('legacy.label_9f537f977f') }}</option><option value="Cooling">{{ $t('legacy.label_5569ac434d') }}</option><option value="Power cycle">{{ $t('legacy.label_afef1fc8f7') }}</option><option value="Lock">{{ $t('legacy.label_891ebccd5b') }}</option></select></div><div class="actions"><button class="btn" @click="typeFilter='all'">{{ $t('legacy.label_719ea396ad') }}</button></div></div>
    <div class="records-quick-actions"><RouterLink class="btn records-view-button" to="/remoteactuation/records/actuators"><i class="pi pi-list"></i> {{ $t('records.viewAll') }} · {{ $t('records.datasets.actuators') }}</RouterLink></div>
    <div class="actuator-grid"><article v-for="actuator in actuators" :key="actuator.id" class="actuator-card"><div class="card-header"><div><h3>{{ actuator.name }}</h3><p>{{ actuator.code }}</p></div><LocalizedStatusBadge :status="actuator.status"/></div><div class="pair-grid"><div class="pair-box"><span>{{ $t('legacy.label_3deb745651') }}</span><strong>{{ actuator.type }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_db6e7e4104') }}</span><strong>{{ $t(`platformUi.state_${actuator.safetyState}`) }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_c19d18023e') }}</span><strong>{{ actuator.linkedSensorId }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_a725020675') }}</span><strong>{{ actuator.running ? $t('uiReview.remoteRunning') : actuator.lastCommand }}</strong></div></div><div v-if="demo.commandInProgress === actuator.id" class="progress"><i style="width: 55%"></i></div><div class="actions"><button class="btn small primary" :disabled="!auth.hasPermission('actuation.execute') || actuator.status!=='online' || actuator.safetyState!=='enabled' || demo.commandInProgress===actuator.id" @click="command(actuator,'Start')">{{ $t('legacy.label_952f375412') }}</button><button class="btn small" :disabled="!auth.hasPermission('actuation.execute') || actuator.status!=='online' || actuator.safetyState!=='enabled'" @click="command(actuator,'Stop')">{{ $t('legacy.label_9e253470c8') }}</button><button class="btn small warning" :disabled="!auth.hasPermission('actuation.execute') || actuator.status!=='online' || actuator.safetyState!=='enabled'" @click="command(actuator,'Reset')">{{ $t('legacy.label_44c57abd88') }}</button></div></article></div>
    <div class="grid-2"><article class="record-summary-card card table-card" role="link" tabindex="0" aria-label="remoteCommands" @click="openRecords('remoteactuation','remoteCommands',$event)" @keydown.enter.self.prevent="openRecords('remoteactuation','remoteCommands')" @keydown.space.self.prevent="openRecords('remoteactuation','remoteCommands')"><div class="card-header"><div><p class="eyebrow">{{ $t('legacy.label_eeda843072') }}</p><h2>{{ $t('legacy.label_cb815f0abf') }}</h2></div></div><table class="responsive-table"><thead><tr><th>{{ $t('legacy.label_8901895fb1') }}</th><th>{{ $t('legacy.label_a5a74a6df0') }}</th><th>{{ $t('legacy.label_bae7d5be70') }}</th><th>{{ $t('legacy.label_5108c2f7e9') }}</th><th>{{ $t('legacy.label_accf40c89b') }}</th></tr></thead><tbody><tr v-for="cmd in demo.remoteCommands.slice(0,6)" :key="cmd.id"><td data-label="Command">{{ cmd.command }}</td><td data-label="Device">{{ cmd.device }}</td><td data-label="Status"><LocalizedStatusBadge :status="cmd.status"/></td><td data-label="Requested by">{{ cmd.requestedBy }}</td><td data-label="Created">{{ new Date(cmd.createdAt).toLocaleString() }}</td></tr></tbody></table></article><article class="card"><div class="card-header"><div><p class="eyebrow">{{ $t('legacy.label_f2a8299745') }}</p><h2>{{ $t('legacy.label_fc59ca6ed3') }}</h2></div></div><div class="item-list"><div class="list-row"><span><strong>{{ $t('legacy.label_11e68f531d') }}</strong><small>{{ $t('legacy.label_dbaf98ac3c') }}</small></span><span class="status-pill success">{{ $t('legacy.label_a733b809d2') }}</span></div><div class="list-row"><span><strong>{{ $t('legacy.label_1c8861906c') }}</strong><small>{{ $t('legacy.label_56fa306252') }}</small></span><span class="status-pill success">{{ $t('legacy.label_a733b809d2') }}</span></div></div></article></div>
  </section>
</template>
